//! Associated entity types and operation outcomes.
//!
//! [`PrimaryKeyOf`] is SeaORM's complete primary-key [`ValueType`](sea_orm::PrimaryKeyTrait::ValueType):
//! a scalar for a single-column key, a tuple for a composite key. Repository
//! methods take this type directly, so UUID and composite keys work without a
//! `From<i32>` bound.

use cgp_fork::prelude::*;
use sea_orm::{EntityTrait, PrimaryKeyTrait};

/// The SeaORM entity this context operates on.
#[cgp_type]
pub trait HasEntityType {
    /// SeaORM entity (the `Entity` unit struct generated by `DeriveEntityModel`).
    type Entity: EntityTrait;
}

/// The [`EntityTrait::Model`] of [`HasEntityType::Entity`].
pub type ModelOf<Context> = <<Context as HasEntityType>::Entity as EntityTrait>::Model;

/// The [`EntityTrait::ActiveModel`] of [`HasEntityType::Entity`].
pub type ActiveModelOf<Context> = <<Context as HasEntityType>::Entity as EntityTrait>::ActiveModel;

/// The [`EntityTrait::Column`] of [`HasEntityType::Entity`].
pub type ColumnOf<Context> = <<Context as HasEntityType>::Entity as EntityTrait>::Column;

/// The complete SeaORM primary-key value of [`HasEntityType::Entity`].
///
/// For a single-column key this is the column's Rust type (`i32`, `Uuid`,
/// …). For a composite key this is a tuple of those types. There is no
/// `From<i32>` requirement.
pub type PrimaryKeyOf<Context> =
    <<<Context as HasEntityType>::Entity as EntityTrait>::PrimaryKey as PrimaryKeyTrait>::ValueType;

/// Outcome of [`CanGetOrCreateEntity::get_or_create`](crate::components::CanGetOrCreateEntity::get_or_create).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum InsertOutcome {
    /// A new row was inserted.
    Inserted,
    /// The identity already had a row, or a concurrent insert won the race.
    Existing,
}

/// Outcome of [`CanUpsertEntity::upsert`](crate::components::CanUpsertEntity::upsert).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum UpsertOutcome {
    /// A new row was inserted.
    Inserted,
    /// An existing row was found (or a unique conflict was handled) and merged.
    Updated,
}
